import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"FAQ & troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md","lastUpdated":1787002545000}`),a={name:`guide/faq.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="faq-troubleshooting" tabindex="-1">FAQ &amp; troubleshooting <a class="header-anchor" href="#faq-troubleshooting" aria-label="Permalink to “FAQ &amp; troubleshooting”">​</a></h1><h2 id="the-three-errors-that-cover-almost-everything" tabindex="-1">The three errors that cover almost everything <a class="header-anchor" href="#the-three-errors-that-cover-almost-everything" aria-label="Permalink to “The three errors that cover almost everything”">​</a></h2><h3 id="_401-unauthorized" tabindex="-1"><code>401 Unauthorized</code> <a class="header-anchor" href="#_401-unauthorized" aria-label="Permalink to “401 Unauthorized”">​</a></h3><p>The token is wrong, expired or revoked. Linkwarden tokens can carry an expiry and can be revoked under <strong>Settings → Access Tokens</strong>; both answer 401, indistinguishably.</p><p>Check that the value starts with <code>ey</code> — Linkwarden&#39;s tokens are NextAuth JWTs. If it does not, a session cookie or a password was probably pasted in. The server warns about this at startup, before the first failing call.</p><h3 id="_403-forbidden" tabindex="-1"><code>403 Forbidden</code> <a class="header-anchor" href="#_403-forbidden" aria-label="Permalink to “403 Forbidden”">​</a></h3><p>The token is valid but its account lacks permission. Collections are shared per member with separate create/update/delete flags, so an account can see a collection and still not be allowed to write to it. Check the collection&#39;s members in Linkwarden.</p><p><code>get_worker_stats</code> returns 403 for everyone except an administrator account. That is expected, not a misconfiguration.</p><h3 id="a-redirect-error" tabindex="-1">A redirect error <a class="header-anchor" href="#a-redirect-error" aria-label="Permalink to “A redirect error”">​</a></h3><p>Requests never follow redirects — that is deliberate, because a redirect would replay the <code>Authorization</code> header to whatever host it names. If you get one, <code>LINKWARDEN_URL</code> is pointing at something that redirects: usually <code>http://</code> where the instance forces <code>https://</code>, or a host that redirects to a canonical domain.</p><p>Set <code>LINKWARDEN_URL</code> to the final URL. A <code>/api/v1</code> suffix is handled for you.</p><h2 id="why-does-search-find-nothing-useful" tabindex="-1">Why does search find nothing useful? <a class="header-anchor" href="#why-does-search-find-nothing-useful" aria-label="Permalink to “Why does search find nothing useful?”">​</a></h2><p>Because your Linkwarden probably does not run Meilisearch.</p><p>Linkwarden parses <code>search_links</code> field filters — <code>tag:</code>, <code>collection:</code>, <code>pinned:</code>, <code>before:</code>, <code>after:</code> and <code>!</code> for negation — <strong>only in its Meilisearch branch</strong>. Without Meilisearch the whole query is matched as a single literal substring, so <code>tag:news</code> looks for those nine characters in your titles and descriptions and finds nothing.</p><p>The server detects this case and says so in the result. Two ways forward:</p><ul><li><strong>Filter structurally instead.</strong> The <code>collection_id</code>, <code>tag_id</code> and <code>pinned_only</code> arguments are applied by the database and work either way. This is the reliable answer.</li><li><strong>Run Meilisearch.</strong> Linkwarden&#39;s own documentation covers the setup, after which the field filters work as advertised.</li></ul><p>Plain search terms without a <code>field:</code> prefix work in both configurations.</p><h2 id="get-link-content-says-there-is-no-readable-archive" tabindex="-1"><code>get_link_content</code> says there is no readable archive <a class="header-anchor" href="#get-link-content-says-there-is-no-readable-archive" aria-label="Permalink to “get_link_content says there is no readable archive”">​</a></h2><p>Only the <em>readable</em> format can be served as text. The screenshot, PDF and single-file HTML archives are binary or raw markup, and turning them into text would be worse than useless.</p><p>The result tells you which formats do exist. If <code>readable</code> is missing:</p><ul><li><strong>Preservation may still be running.</strong> <code>get_worker_stats</code> shows the queue (admin accounts only).</li><li><strong>It may have failed.</strong> <code>represerve_link</code> drops the existing archives and tries again.</li><li><strong>It may be switched off.</strong> Check <code>archiveAsReadable</code> in the account defaults (<code>get_current_user</code>) and any per-tag override (<code>list_tags</code>).</li></ul><h2 id="why-did-a-bookmark-lose-its-tags-when-i-renamed-it" tabindex="-1">Why did a bookmark lose its tags when I renamed it? <a class="header-anchor" href="#why-did-a-bookmark-lose-its-tags-when-i-renamed-it" aria-label="Permalink to “Why did a bookmark lose its tags when I renamed it?”">​</a></h2><p>It should not, and with this server it does not — but it is worth knowing why the question comes up. Linkwarden&#39;s <code>PUT /links/{id}</code> is a <strong>replacement</strong>: it applies tags with <code>set: []</code> first and writes <code>name</code>/<code>description</code> as <code>data.name || &quot;&quot;</code>. A partial body therefore erases whatever it omits.</p><p>This server reads the current record and merges before writing, so omitted fields keep their values. If you drive the API directly, you have to do the same.</p><h2 id="why-does-deleting-a-collection-remove-links" tabindex="-1">Why does deleting a collection remove links? <a class="header-anchor" href="#why-does-deleting-a-collection-remove-links" aria-label="Permalink to “Why does deleting a collection remove links?”">​</a></h2><p>Because Linkwarden cascades: a collection&#39;s links and its sub-collections go with it. That is why <code>delete_collection</code> requires a confirmation token and says so in the prompt.</p><p>To keep the links, move them to another collection first — <code>bulk_update_links</code> can do that for a whole batch.</p><h2 id="why-does-update-link-sometimes-want-a-confirmation-and-sometimes-not" tabindex="-1">Why does <code>update_link</code> sometimes want a confirmation and sometimes not? <a class="header-anchor" href="#why-does-update-link-sometimes-want-a-confirmation-and-sometimes-not" aria-label="Permalink to “Why does update_link sometimes want a confirmation and sometimes not?”">​</a></h2><p>Only when you change the <strong>URL</strong>. Linkwarden deletes every preserved copy of the old page when the URL changes, which is irreversible, so it is treated like a deletion. Changing the title, description, tags or collection needs no confirmation.</p><p>The same asymmetry applies to <code>update_collection</code>: publishing a collection (<code>is_public=true</code>) needs a confirmation, unpublishing does not.</p><h2 id="can-i-stop-it-from-writing-anything" tabindex="-1">Can I stop it from writing anything? <a class="header-anchor" href="#can-i-stop-it-from-writing-anything" aria-label="Permalink to “Can I stop it from writing anything?”">​</a></h2><p><code>LINKWARDEN_READ_ONLY=true</code>. The write tools are not registered at all — they never appear in <code>tools/list</code>. Pair it with an account that only has read access for a belt-and-braces setup.</p><h2 id="creating-a-link-created-a-duplicate-collection" tabindex="-1">Creating a link created a duplicate collection <a class="header-anchor" href="#creating-a-link-created-a-duplicate-collection" aria-label="Permalink to “Creating a link created a duplicate collection”">​</a></h2><p>If you pass a collection <strong>name</strong> that already exists, Linkwarden&#39;s raw API happily creates a second collection with the same name — names are not unique. Pass <code>collection_id</code> when you mean an existing collection, and <code>collection_name</code> only when you want one created.</p><p><code>list_collections</code> gives you the ids.</p><h2 id="self-signed-certificate" tabindex="-1">Self-signed certificate <a class="header-anchor" href="#self-signed-certificate" aria-label="Permalink to “Self-signed certificate”">​</a></h2><p><code>LINKWARDEN_INSECURE_TLS=true</code> accepts it, scoped to this connection only. Better: add your internal CA to the system trust store or point <code>NODE_EXTRA_CA_CERTS</code> at it, which keeps validation intact.</p><h2 id="which-linkwarden-versions-work" tabindex="-1">Which Linkwarden versions work? <a class="header-anchor" href="#which-linkwarden-versions-work" aria-label="Permalink to “Which Linkwarden versions work?”">​</a></h2><p>Developed and verified against <strong>v2.16.0</strong>. Nearby versions are very likely fine — the v1 API is stable in practice — but Linkwarden&#39;s published API reference is incomplete, so this server was written against the route handlers themselves. If a tool misbehaves on your version, please <a href="https://github.com/ni-c/linkwarden-mcp/issues" target="_blank" rel="noreferrer">open an issue</a> with the version number.</p><h2 id="something-else" tabindex="-1">Something else <a class="header-anchor" href="#something-else" aria-label="Permalink to “Something else”">​</a></h2><ul><li>Questions and ideas → <a href="https://github.com/ni-c/linkwarden-mcp/discussions" target="_blank" rel="noreferrer">Discussions</a></li><li>Reproducible problems → <a href="https://github.com/ni-c/linkwarden-mcp/issues" target="_blank" rel="noreferrer">Issues</a></li><li>Vulnerabilities → <a href="https://github.com/ni-c/linkwarden-mcp/security/advisories/new" target="_blank" rel="noreferrer">private reporting</a></li></ul>`,41)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};